const l={1:10,2:60,3:480,4:1440},E={1:{nombre:"Muy alta",plazo:"10 min",color:"#B4232A",fondo:"#FCEFEF"},2:{nombre:"Alta",plazo:"1 hora",color:"#B45309",fondo:"#FFF4E0"},3:{nombre:"Media",plazo:"8 horas",color:"#2A377E",fondo:"#EEF3FF"},4:{nombre:"Baja",plazo:"24 horas",color:"#3D4A63",fondo:"#EEF1F6"}},m=1;function c(n){const t=Math.abs(Math.round(n));if(t<60)return`${t} min`;if(t<1440){const a=Math.floor(t/60),i=t%60;return i?`${a} h ${i} min`:`${a} h`}const o=Math.floor(t/1440),e=Math.floor(t%1440/60);return e?`${o} d ${e} h`:`${o} d`}function f(n,t=new Date){const o=Number(n?.criticidad)||null;if(!o||!l[o])return{estado:"sin-plazo",nivel:null,texto:"Sin plazo"};const e=l[o],a=n.fecha_inicio?new Date(n.fecha_inicio):null;if(!a||Number.isNaN(a.getTime()))return{estado:"sin-plazo",nivel:o,texto:"Sin fecha"};if(Number(n.estado_id)!==m){const s=n.fecha_primera_respuesta?new Date(n.fecha_primera_respuesta):null;if(!s||Number.isNaN(s.getTime()))return{estado:"atendido",nivel:o,texto:"Atendido"};const d=(s-a)/6e4;return{estado:"atendido",nivel:o,minutos:d,dentroDePlazo:d<=e,texto:`Atendido en ${c(d)}`}}const u=(t-a)/6e4,r=e-u;return r<0?{estado:"vencido",nivel:o,minutos:r,consumido:1,texto:`Vencido hace ${c(r)}`}:{estado:r/e<.3?"aviso":"ok",nivel:o,minutos:r,consumido:Math.max(0,Math.min(1,u/e)),texto:`Quedan ${c(r)}`}}const h={ok:"bg-[#E6F4ED] text-[#1C6B4B]",aviso:"bg-[#FFF4E0] text-[#B45309]",vencido:"bg-[#FCEFEF] text-[#B4232A]",atendido:"bg-[#EEF1F6] text-[#5E6A82]","sin-plazo":"bg-transparent text-[#94A1B6]"};export{h as E,E as N,l as P,f as e,c as f};
